\foreach \v/\lab in {0.25/{0.25},0.5/{0.5},0.75/{0.75},1/{1}} {\draw[black] (1.95,\v)--(2,\v);\path (1.95,\v) node[left,font=\fontsize{8.5}{10}\selectfont] {$\lab$};}
\path (2,0) node[below] {$2$};
\path (3.914868,0) node[below] {$Q_1$};
\path (4.820285,0) node[below] {$m$};
\path (5.473704,0) node[below] {$Q_3$};
\path (6,1) node[right] {$(6,1)$};
\end{tikzpicture}
